from __future__ import annotations

import json
from datetime import datetime, timedelta, timezone
from pathlib import Path

import pytest


def sample_manifest(job_id: str = "test-001", *, hours_ahead: int = 48) -> dict:
    return {
        "job_id": job_id,
        "title": "Automated research video",
        "description": "Generated by a test fixture.",
        "video_file": "video.mp4",
        "thumbnail_file": "cover.png",
        "subtitle_file": "captions.srt",
        "subtitle_language": "zh-CN",
        "tags": ["research", "video"],
        "category_id": "28",
        "target_channel": "main",
        "publish_at": (datetime.now(timezone.utc) + timedelta(hours=hours_ahead))
        .isoformat(),
        "ready": True,
        "review_approved": True,
        "rights_confirmed": True,
        "made_for_kids": False,
        "contains_synthetic_media": False,
    }


@pytest.fixture
def ready_assets(tmp_path: Path) -> Path:
    directory = tmp_path / "assets" / "test-001"
    directory.mkdir(parents=True)
    (directory / "video.mp4").write_bytes(b"FAKE_MP4_FOR_TESTS_ONLY")
    (directory / "cover.png").write_bytes(b"FAKE_PNG_FOR_TESTS_ONLY")
    (directory / "captions.srt").write_text(
        "1\n00:00:00,000 --> 00:00:01,000\nhello\n", encoding="utf-8"
    )
    (directory / "manifest.json").write_text(
        json.dumps(sample_manifest(), ensure_ascii=False), encoding="utf-8"
    )
    return directory.parent
